    "Башни исправлены: приподнятые двери на уровне арены удалены, потому что они лишь оставляли проход мобам снизу и не давали полезной функции.",
    "Входы из башен в музей опущены на пол: двери занимают y65–67 над полом y68.",
    "Зигзагообразные платформы заменены на сквозные зеркальные платформы полной ширины на уровнях y18, y24, y30, y36, y56 и y62.",
    "Верхние люки башен теперь встроены в настоящий пол y41 с двухтайловым проёмом, а не висят в открытой шахте.",
    "Для всех сундуков восстановлены подробные подсказки: внешний вид, точное назначение, примеры содержимого и правило «не сюда».",
    "Рабочий склад переделан в 80 сундуков: 5 этажей × 2 вертикали × 2 ряда × 4 сундука.",
    "Левая вертикаль хранит нестакуемое; правая — стакающееся, строительство и инженерную инфраструктуру.",
    "Нестакуемые предметы: минимум два экземпляра, важные — до пяти; шестой и последующие идут в L1.2 «ПРОДАТЬ».",
    "Сундуковая матрица v2: модель сундука показывает крупную смысловую семью, краска — подкатегорию, фон и свет — этаж.",
    "Stone Chest закреплён за рудами/слитками и минеральной стройкой; Gold Chest — за ценностями и парадными категориями.",
    "Каждый полный ряд использует 38 посадочных тайлов: длины групп 5/5/6/6/6/5/5 плюс шесть одноклеточных разделителей.",
    "Все 87 сундуков получили уникальные имена для ввода в игре; максимальная длина 19 символов при лимите 20.",
    "Теплица сжата до четырёх ярусов: y−1, y1, y3 и y5; между ярусами ровно один пустой тайл.",
    "Стеклянная крыша опущена до y−3; внешний габарит теплицы теперь 46×10.",
    "Три верхних яруса полные по 38 посадочных тайлов; нижний содержит 32 тайла и не имеет Waterleaf-секции над сундуками и люком.",
    "Waterleaf расположен на y−1, y1 и y3; нижний ряд y3 находится прямо над SEED и HARVEST.",
    "Шесть White Torch стоят в горизонтальных разделителях второго яруса y1 с интервалом 6–7 тайлов.",
    "Фоновые стены крафтовой передизайнены по выборочной четырёхзонной схеме: этажи 2 и 4 имеют полноценное цветовое деление, этажи 1 и 3 спокойнее, этаж 5 остаётся единой белой галереей.",
    "Центральная ось x67–68 на рабочих этажах 1–4 выделена Stone Slab Wall + Black Paint; геометрия и расположение мебели не изменены.",
    "За межэтажными платформами крафтовой теперь проставлены фоновые стены: каждая платформа получает тот же фон, что и зона непосредственно под ней.",
    "Исправлены пропущенные фоновые стены за платформами, дверями и люками; заполнены локальные архитектурные дыры в x45,y13 и x90,y13; правая башня выровнена по x135, грибной павильон больше не нависает столбцом над башней на x127.",
    "Пересобран нижний край грибного павильона: трюфельный потолок над клиникой убран, вместо него непрерывный серый потолок с люком H_MUSH в x120–121 и фоном clinic_wall под ним.",
    "Грибной павильон уточнён: ряды Mushroom Grass находятся на y7, y9, y13, y15, y19 и y21 (126 тайлов). Трёхклеточные проходы для игрока находятся на y10–12 и y16–18, а платформы в шахте x120–121 стоят на уровнях y13 и y19.",
    "Матрица исправлена после фактического заполнения: два сундука Quest Fish удалены. R4.7 теперь хранит платформы/верёвки/цепи, R4.8 — факелы и переносной свет; стены распределяются вместе с базовым материалом между R2.7 и R2.8.",
    "Световой склад уточнён: Campfire, Heart Lantern, Star in a Bottle, факелы, glowsticks и flares идут в R4.8 «Свет и бафы»; декоративные интерьерные светильники — в R5.6.",
    "Красильное хранение вынесено из R5.8 в шесть центральных сундуков пятого этажа: D5.1 сырьё, D5.2–D5.4 три каталога обычных красителей, D5.5 Hair Dyes, D5.6 Paint/Coatings. R5.8 стал вторым сундуком статуй и трофеев.",
    "Боевая улица подтверждена как 12 тайлов чистой высоты (y42–53). Мёд больше не нарисован свободной массой: добавлены две реальные одноклеточные купели со стеклянными бортами и существующим полом y54 как дном.",
    "Арена M1: по две actuated Dart Trap в каждой из четырёх кассет, два локальных 1/2 Second Timer, отдельные ARM/PHASE/HEART цепи и синяя кнопка центрального люка. В потолке отмечены 12 резервных слотов M2/M3.",
    "Инженерный слой M1 исправлен: Dart Trap, 1/2 Second Timer и Switch теперь явно занимают передний тайл в инспекторе; таймеры исправлены до 1×1, фиктивные 1×1 Lever заменены реальными Switch 1×1.",
    "Встречные Dart Trap на x108/x125 и симметричных линиях оставлены намеренно: схема рассчитана на actuated/inactive (ghost) ловушки; инспектор теперь показывает направление, пару и обязательное условие ghost.",
    "Арена M1 пересобрана по результату реальной сборки: крайние Dart Trap один раз утоплены временными актуаторами, после чего актуаторы сняты; внутренние ловушки остаются твёрдыми. Боевой таймер больше не может переключать состояние блоков.",
    "Фиктивные прямоугольники пультов и отдельное управление центральным люком удалены. Люк открывается вручную; в центре стоят только реальные Switch и Timer для ловушек и Heart Statue.",
    "Левая босс-арена передизайнена: четыре платформы y11/y21/y31/y41 с шагом 10, пять колонн шириной 5 с наружным Gray Brick Wall и внутренним Stone Slab Wall, четыре верхних песчаниково-облачных оконных пролёта, два твёрдых лазерных навеса и две проходные медовые ванны 3×3 внутри Bubble. Краски не используются.",
    "Освещение левой босс-арены переделано без факелов и Chain Lantern: четыре верхних окна и двадцать ромбовых орнаментов колонн используют Diamond Gemspark Wall. Источники находятся в фоне, не занимают передний тайл и не снимаются случайным Open / Activate.",
    "Музей переработан: шесть одинарных разделителей заменены шестью симметричными двойными капителями с молотковыми скосами и низкими цоколями; CH1–CH6/CENTER больше не являются огромными объектами-перекрытиями.",
    "Все семь музейных глав заполнены отдельными физическими экспонатами: трофеями, манекенами, стойками оружия и рамками предметов; больших интерактивных зон поверх комнат нет.",
    "Разделители вокруг Переломного зала получили тёмную сердцевину из Stone Slab + Black Paint, кирпичные скосы и Stone Slab Wall + Black Paint на фоне, поэтому больше не сливаются с белым мраморным залом.",
    "Освещение музея выполнено восемью нишами Diamond Gemspark Wall: 32 светящихся фоновых тайла, не снимаемых случайной правой кнопкой мыши.",
    "Восемь прямоугольных оверлеев кассет/ручного боя/буферов и все Dart Trap с внутренней улицы удалены. В spawn-двориках построены две зеркальные прямоугольные ямы 16 тайлов с актуируемыми мостами, лавой, конвейерами к базе, настенными ловушками и техническими проходами снизу.",
    "Обе 16-тайловые ямы перенесены вплотную к наружным стенам башен: левая x−16…−1, правая x136…151. Отдельные сервисные шахты и поверхностные люки удалены; технические проходы открываются прямо из нижних частей башен.",
    "Пол обоих технических проходов поднят на y68 и теперь непрерывно совпадает с полом музея; над проходом находятся конвейеры y64 и тонкий слой лавы y63.",
    "На стабильную версию pits-v2 повторно применены точные изменения: четыре столбца по 8 Dart Trap на x−18/x−1/x136/x153, Stone Slab-рамки с y55, непрерывный Gray Brick на y54, Lever 2×2 с таймером над ним и опускание всех 10 люков на один тайл."
